    for (i = 0, j = 0; i &lt; 16; ++i, j += 4)
        m[i] = (data[j] &lt;&lt; 24) | (data[j+1] &lt;&lt; 16) | (data[j+2] &lt;&lt; 8) | (data[j+3]);
    for ( ; i &lt; 64; ++i)
        m[i] = SIG1(m[i-2]) + m[i-7] + SIG0(m[i-15]) + m[i-16];

    a = ctx-&gt;state[0];
    b = ctx-&gt;state[1];
    c = ctx-&gt;state[2];
    d = ctx-&gt;state[3];
    e = ctx-&gt;state[4];
