            sha256_transform(ctx, ctx-&gt;data);
            ctx-&gt;bitlen += 512;
            ctx-&gt;datalen = 0;
        }
    }
}

static void sha256_final(SHA256_CTX *ctx, uint8_t hash[]) {
    uint32_t i = ctx-&gt;datalen;

    if (ctx-&gt;datalen &lt; 56) {
        ctx-&gt;data[i++] = 0x80;
        while (i &lt; 56) ctx-&gt;data[i++] = 0x00;
    } else {
        ctx-&gt;data[i++] = 0x80;
        while (i &lt; 64) ctx-&gt;data[i++] = 0x00;
