        hash[i]      = (ctx-&gt;state[0] &gt;&gt; (24 - i * 8)) &amp; 0xff;
        hash[i + 4]  = (ctx-&gt;state[1] &gt;&gt; (24 - i * 8)) &amp; 0xff;
