    if (!f) return 0;
    char line[1024];
    int ok = 0;
    while (fgets(line, sizeof(line), f)) {
        char *nl = strchr(line, '\n'); if (nl) *nl = 0;
        if (!*line || line[0] == '#') continue;
        char *u = line;
        char *c1 = strchr(u, ':'); if (!c1) continue; *c1 = 0;
        char *s = c1 + 1;
        char *c2 = strchr(s, ':'); if (!c2) continue; *c2 = 0;
        char *h = c2 + 1;
        if (strcmp(u, username) == 0) {
            char hex[65];
            if (!hexstr_from_salted(s, password, hex)) { fclose(f); return 0; }
            if (constant_time_eq(hex, h)) { ok = 1; break; }
        }
    }
    fclose(f);
    return ok;
}

static int authenticate_builtin(const char *username, const char *password) {
    /* demo users; not for production */
    const char *demo_pwd1 = "demo123";
    const char *demo_pwd2 = "wonderland";
    user_record users[] = {
        { "demo",  "s1",  NULL },
        { "alice", "NaCl",""   }
    };
    char hex[65];
    if (strcmp(username, "demo") == 0) {
        if (!hexstr_from_salted("s1", password, hex)) return 0;
        char exp[65];
        if (!hexstr_from_salted("s1", demo_pwd1, exp)) return 0;
        return constant_time_eq(hex, exp);
    } else if (strcmp(username, "alice") == 0) {
        if (!hexstr_from_salted("NaCl", password, hex)) return 0;
        char exp[65];
        if (!hexstr_from_salted("NaCl", demo_pwd2, exp)) return 0;
        return constant_time_eq(hex, exp);
    }
    (void)users;
    return 0;
}

static void html_escape(const char *in, char *out, size_t outlen) {
    size_t di = 0;
    for (size_t i = 0; in[i] &amp;&amp; di + 6 &lt; outlen; ++i) {
        char c = in[i];
        if (c == '&lt;')      { di += snprintf(out + di, outlen - di, "&amp;lt;"); }
        else if (c == '&gt;') { di += snprintf(out + di, outlen - di, "&amp;gt;"); }
        else if (c == '&amp;'){ di += snprintf(out + di, outlen - di, "&amp;amp;"); }
        else if (c == '\"')  { di += snprintf(out + di, outlen - di, "&amp;quot;"); }
        else if (c == '\'')  { di += snprintf(out + di, outlen - di, "&#39;"); }
        else out[di++] = c;
        if (di &gt;= outlen) break;
    }
    out[di] = 0;
}

static void respond(int code, const char *status, const char *body) {
    printf("Status: %d %s\r\n", code, status);
    printf("Content-Type: text/html; charset=utf-8\r\n\r\n");
    printf("%s", body);
}

int main(void) {
    const char *method = getenv("REQUEST_METHOD");
    const char *ctype = getenv("CONTENT_TYPE");
    const char *users_db = getenv("USERS_DB");
    if (!users_db || !*users_db) users_db = "/workspace/users.db";

    char username[256] = {0}, password[256] = {0};

    if (!method) {
        respond(500, "Internal Server Error", "&lt;h1&gt;CGI environment missing REQUEST_METHOD&lt;/h1&gt;");
        return 0;
    }

    char bodybuf[4096] = {0};
    if (strcmp(method, "POST") == 0) {
        const char *cl = getenv("CONTENT_LENGTH");
        long clen = cl ? strtol(cl, NULL, 10) : 0;
        if (clen &lt; 0 || clen &gt;= (long)sizeof(bodybuf)) {
            respond(413, "Payload Too Large", "&lt;h1&gt;Payload too large&lt;/h1&gt;");
            return 0;
        }
        size_t readn = 0;
        while (readn &lt; (size_t)clen) {
            size_t n = fread(bodybuf + readn, 1, (size_t)clen - readn, stdin);
            if (n == 0) break;
            readn += n;
        }
        bodybuf[readn] = 0;
    } else if (strcmp(method, "GET") == 0) {
        const char *qs = getenv("QUERY_STRING");
        if (qs) strncpy(bodybuf, qs, sizeof(bodybuf)-1);
    } else {
        respond(405, "Method Not Allowed", "&lt;h1&gt;Method Not Allowed&lt;/h1&gt;");
        return 0;
    }

    if (!get_param(bodybuf, "username", username, sizeof(username)) ||
        !get_param(bodybuf, "password", password, sizeof(password))) {
        const char *form =
            "Content-Type: text/html; charset=utf-8\r\n\r\n"
            "&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;"
            "&lt;h1&gt;Login&lt;/h1&gt;"
            "&lt;form method='POST'&gt;"
            "Username: &lt;input name='username' /&gt;&lt;br/&gt;"
            "Password: &lt;input name='password' type='password' /&gt;&lt;br/&gt;"
            "&lt;button type='submit'&gt;Login&lt;/button&gt;"
            "&lt;/form&gt;"
            "&lt;/body&gt;&lt;/html&gt;";
        printf("%s", form);
        return 0;
    }

    char user_esc[512]; html_escape(username, user_esc, sizeof(user_esc));
    int ok = 0;
    if (file_exists(users_db)) {
        ok = authenticate_file(users_db, username, password);
    } else {
        ok = authenticate_builtin(username, password);
    }

    if (ok) {
        char msg[1024];
        snprintf(msg, sizeof(msg),
            "&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Welcome, %s&lt;/h1&gt;&lt;p&gt;Authentication successful.&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;",
            user_esc);
        respond(200, "OK", msg);
    } else {
        respond(401, "Unauthorized",
            "&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Unauthorized&lt;/h1&gt;&lt;p&gt;Invalid credentials.&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;");
    }
    return 0;
}

